for (const row of data) {
  const replacement = replacements[row[1]];
  if (replacement) {
    row[1] = replacement[0];
    row[2] = replacement[1];
    row.splice(4,3,...replacement.slice(2));
  }
}

const locales = ['en','hi','pa'];
const answerPositions = [2,0,3,1,3,1,0,2,1,3,2,0,2];
for (const cp of ['CP029','CP030','CP031','CP032']) {
  const rows = data.filter(row => row[0] === cp).map((row, i) => {
    const [_, objective, difficulty, sourceIds, ...variants] = row;
    const localized = Object.fromEntries(locales.map((lang, n) => {
      const [stem, answer, distractors, explanation] = variants[n];
      const options = [answer, ...distractors];
      // Fixed rotation keeps answer positions distributed while preserving language parity.
      const correctIndex = answerPositions[i];
      const shift = (4 - correctIndex) % 4;
      const shuffled = options.slice(shift).concat(options.slice(0, shift));
      return [lang, { stem, options: shuffled, explanation }];
    }));
    return { id: `WGE-001-${cp}-Q${String(i+1).padStart(3,'0')}`, cpId: `WGE-001-${cp}`, objective, difficulty, sourceIds, correctIndex: answerPositions[i], locales: localized };
  });
  writeFileSync(`artifacts/api-server/src/knowledge-v1/world-geography/${cp.toLowerCase().replace('cp','cp')}.json`, `${JSON.stringify(rows,null,2)}\n`);
}
